/bin/zsh -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import { checkout } from './src/app.js';
import { makeReceiptKey as billingKey } from './src/billing/receipt.js';
import { makeReceiptKey as reportKey } from './src/reports/receipt.js';
import { makeReceiptKey as responseKey } from './src/transport/receipt.js';

const answer = JSON.parse(await readFile('answer.json', 'utf8'));
assert.deepEqual(Object.keys(answer), ['owner_file', 'owner_symbol', 'outbound_file', 'outbound_symbol', 'call_chain', 'example_key']);
const invoice = { accountId: 'acme', sequence: 7 };
let sent;
await checkout(invoice, { post: async (...args) => { sent = args; } });
assert.equal(billingKey(invoice), answer.example_key);
assert.deepEqual(sent, ['/invoices', invoice, { 'Idempotency-Key': answer.example_key }]);
assert.equal(reportKey({ id: 7 }), 'report:7');
assert.equal(responseKey({ headers: { 'x-receipt': 'received' } }), 'received');
console.log('PASS: answer schema, checkout outbound header, and distinct receipt helpers');
NODE"

